import{_ as i,o as n,c as t,a2 as a}from"./chunks/framework.BWuWLRhz.js";const m=JSON.parse('{"title":"Plugins and Extensions","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/plugins-and-extensions.md","filePath":"architecture/plugins-and-extensions.md","lastUpdated":null}'),o={name:"architecture/plugins-and-extensions.md"};function r(l,e,s,c,d,p){return n(),t("div",null,[...e[0]||(e[0]=[a('<h1 id="plugins-and-extensions" tabindex="-1">Plugins and Extensions <a class="header-anchor" href="#plugins-and-extensions" aria-label="Permalink to &quot;Plugins and Extensions&quot;">​</a></h1><p><strong>Status:</strong> Approved foundation<br><strong>Date:</strong> 2026-07-28<br><strong>Beads issue:</strong> <code>archie-core-5d7</code></p><h2 id="plugin-framework" tabindex="-1">Plugin framework <a class="header-anchor" href="#plugin-framework" aria-label="Permalink to &quot;Plugin framework&quot;">​</a></h2><p>The core plugin domain lives under <code>internal/domain/plugin</code>. It owns:</p><ul><li>plugin identity and metadata;</li><li>discovery and registration contracts;</li><li>lifecycle rules;</li><li>capability registration;</li><li>validation and compatibility rules.</li></ul><p>The generic plugin contract remains metadata-only. Functionality is exposed through narrow typed capability contracts with an owning registry or manager.</p><p>Workflow plugins belong to the Workflow capability family. The Workflow domain at <code>internal/domain/workflow</code> owns their typed registration, validation, versioning, definition, and execution contracts. The generic plugin domain may provide plugin identity, discovery, compatibility, and lifecycle mechanics, but it MUST NOT define Workflow semantics or expose untyped Workflow hooks.</p><h2 id="plugin-implementations" tabindex="-1">Plugin implementations <a class="header-anchor" href="#plugin-implementations" aria-label="Permalink to &quot;Plugin implementations&quot;">​</a></h2><p>First-party plugins are self-contained vertical modules under <code>plugins/&lt;plugin&gt;</code>.</p><p>A plugin:</p><ul><li>owns its implementation, settings, templates, assets, and tests;</li><li>receives only explicitly supplied contracts and services;</li><li>MUST NOT receive daemon internals, a service locator, or unrestricted application access;</li><li>MUST NOT import arbitrary infrastructure or application composition code;</li><li>MAY use approved domain and shared application contracts;</li><li>MUST remain removable without changes to unrelated domains.</li></ul><p>Plugins may be internally cohesive like small services. They do not become network services without a concrete security or operational reason.</p>',12)])])}const g=i(o,[["render",r]]);export{m as __pageData,g as default};
